#!/usr/bin/env python3
"""Generates workspace/work/log.md from the headers of work/<item>/status.md. Do not edit log.md by hand."""
import pathlib, re, datetime
root = pathlib.Path(__file__).resolve().parent.parent / "work"
OPEN = {"active", "awaiting-feedback", "blocked"}
rows = []
for p in sorted(root.glob("*/status.md")):
    if p.parent.name.startswith("_"):
        continue
    m = re.match(r"^---\n(.*?)\n---", p.read_text(encoding="utf-8"), re.S)
    fm = {}
    for line in (m.group(1).splitlines() if m else []):
        if ":" in line and not line.startswith(" "):
            k, v = line.split(":", 1)
            fm[k.strip()] = v.strip()
    rows.append((p.parent.name, fm))
today = datetime.date.today()
def age(fm):
    try:
        return (today - datetime.date.fromisoformat(fm.get("updated", ""))).days
    except ValueError:
        return None
out = ["# Work log (generated by: python3 workspace/scripts/work_log.py; do not edit by hand)", "",
       f"Generated: {today}. Open items not updated for more than 5 days get a warning.", ""]
for title, pred in (("Open", lambda s: s in OPEN), ("Closed", lambda s: s not in OPEN)):
    out += [f"## {title}", "", "| work | status | domain | next step | waiting on | updated | days |", "|---|---|---|---|---|---|---|"]
    for name, fm in rows:
        if pred(fm.get("status", "?")):
            a = age(fm)
            warn = " ⚠" if (a is not None and a > 5 and title == "Open") else ""
            out.append(f"| [{name}]({name}/status.md) | {fm.get('status','?')} | {fm.get('domain','')} | {fm.get('next_step','')} | {fm.get('waiting_on','')} | {fm.get('updated','')} | {a if a is not None else '?'}{warn} |")
    out.append("")
(root / "log.md").write_text("\n".join(out), encoding="utf-8")
print(f"{len(rows)} work items listed")
